sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_bare, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.source_type AS dict_source_type, d.period AS dict_period, d.author AS dict_author, d.death_year AS dict_death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('كفاية','الكفاية','ملاءمة','الملاءمة','اجزاء','الاجزاء','وفاء','الوفاء','اكتفاء','الاكتفاء','غناء','الغناء') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
for r in data:
    print(f\"[{r['headword_norm']}] id={r['entry_id']} dict={r['dict_name_ar']} src={r['dict_source_type']} root={r['root']} pos={r['pos']}\")
    if r['definitions_text']: print(f\"  def: {r['definitions_text'][:200]}\")
    if r['translation_en']: print(f\"  en: {r['translation_en']}\")
    if r['domain']: print(f\"  domain: {r['domain']}\")
print(f'--- Total: {len(data)} ---')
"

